import type { Language } from "@/lib/i18n";
import { BRAND } from "@/lib/brands";
import type { CapturedRecord } from "@/types";
import type { ReplyButton } from "./types";

/**
 * =============================================================================
 *  WhatsApp channel copy
 * =============================================================================
 *
 *  Everything the WhatsApp bot says that is *not* generated by the model: the
 *  welcome message, record receipts, escalation notices and the quick-action
 *  chips.
 *
 *  Kept out of `lib/i18n.ts` on purpose — that dictionary serves the web UI,
 *  where labels sit on buttons in a rendered page. These strings are chat
 *  messages: they need emoji, line breaks and a warmer register, and they are
 *  only ever read inside WhatsApp.
 * =============================================================================
 */

type Localised = Record<Language, string>;

export const ACTION_BUTTON_PREFIX = "act:";

function pick(copy: Localised, language: Language): string {
  return copy[language] ?? copy.en;
}

