/**
 * The three chips offered under an answer.
 *
 * "Get a quote" and "Our services" need no handler of their own: a tapped
 * button arrives with its title as the message text, and the representative
 * takes it from there like anything the customer typed.
 */
export function quickActions(language: Language): ReplyButton[] {
  return [
    { id: `${ACTION_BUTTON_PREFIX}capture`, title: pick(GET_QUOTE, language) },
    { id: `${ACTION_BUTTON_PREFIX}services`, title: pick(OUR_SERVICES, language) },
    { id: `${ACTION_BUTTON_PREFIX}human`, title: pick(TALK_TO_TEAM, language) },
  ];
}

